"""iperf"""
from builtins import str, object
import re
import time
from SSHLibrary import SSHClient
from taf.ul.trs_e2e_fw.lib.call_utils.iperf.iperf_exceptions import NoDataReceivedAtIperfServerException
from taf.ul.trs_e2e_fw.lib.call_utils.iperf.iperf_process import IperfProcess
from taf.ul.trs_e2e_fw.lib.call_utils.iperf.builder import Builder
from taf.ul.trs_e2e_fw.lib.call_utils.iperf.iperf_process_interactive_shell import IperfProcessInteractiveShell
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable
from taf.rfrl.trs_e2e_fw.setup.config_handler import ConfigHandler
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
logger = BackgroundLogger.Instance()


class Iperf(object):
    """iperf"""
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(self, ue_ip, iperf_section, profile, ue_type, rat, device_name,
                 adb_id='', ipv4_or_6='ipv4', **kwargs):
        self.iperf_section = iperf_section
        self.config = ConfigHandler.get_config()
        profile_params = get_config_variable(['traffic_profiles', profile])
        self.direction = profile_params['direction']
        bts_id = get_config_variable(['bts_id'])
        self.adb_id = adb_id
        self.ue_ip = ue_ip
        self.rat = rat
        self.device_name = device_name
        self.ue_type = ue_type
        self.android_version = kwargs.get('version')
        iperf_pc_ssh_client, ue_pc_ssh_client = self._start_ssh_sessions()
        self._create_iperf_processes(iperf_pc_ssh_client, ue_pc_ssh_client)
        # self.iperf_process = IperfProcess(iperf_pc_ssh_client)
        iperf_pc_ip = get_config_variable(['iperf', iperf_section, 'ip'])
        iperf_traffic_ip = get_config_variable(['iperf', iperf_section, 'traffic_ip'])
        self.iperf_traffic_ip =\
            iperf_traffic_ip if iperf_traffic_ip else iperf_pc_ip
        # self.builder = Builder(ue_type, adb_id, bts_id, ue_ip, iperf_pc_ip,
        #                        profile_params, **kwargs)
        self.builder = Builder(rat, ue_type, adb_id, bts_id, ue_ip,
                               self.iperf_traffic_ip, profile, ipv4_or_6,
                               iperf_section, **kwargs)

    def _start_ssh_sessions(self):
        ssh_client, ue_pc_ssh_client = None, None
        # if self.ue_type.lower() != 'iphy' and self.ue_type.lower() != 'airphone':
        ssh_client = self._start_ssh_to_iperf_pc()
        ue_pc_ssh_client = self._start_ssh_to_ue_pc()
        return ssh_client, ue_pc_ssh_client

    def start_data(self, alias):
        """Start data"""
        iperf_local_cmd, local_log, iperf_remote_cmd, remote_log =\
            self.builder.build_iperf_commands(alias)
        logger.debug("################ ADB ID ################# {}".format(self.adb_id))
        logger.debug("### iperf_local_cmd {} and log {} ############# iperf_remote_cmd {} and log {} ".format(
            iperf_local_cmd, local_log, iperf_remote_cmd, remote_log))
        if self.adb_id == '':
            iperf_local_cmd, iperf_remote_cmd = self._bind_the_ips(
                iperf_local_cmd, iperf_remote_cmd)
            logger.debug("################ ADB ID ################# {}".format(self.adb_id))
        logger.debug('iperf_local_cmd:\n {} \n \niperf_remote_cmd:\n {}'.format(
            iperf_local_cmd, iperf_remote_cmd))
        self.iperfuepc_process.start_process(iperf_local_cmd, local_log)
        logger.info('Started iperf UE')
        self.iperfpc_process.start_process(iperf_remote_cmd, remote_log)
        logger.info('Started iperf remote')

    def _bind_the_ips(self, iperf_local_cmd, iperf_remote_cmd):
        if self.ue_type.lower() != 'airphone':
            iperf_local_cmd = iperf_local_cmd.format(bind='-B {}'.format(self.ue_ip))
            iperf_remote_cmd = iperf_remote_cmd.format(bind='')
        else:
            bind_ip = get_config_variable(['iperf', self.iperf_section, 'server_bind_ip'])
            # iperf_local_cmd = iperf_local_cmd.format(bind='')
            if self.direction.lower() == 'ul':
                iperf_remote_cmd = iperf_remote_cmd.format(bind=bind_ip)
            elif self.direction.lower() == 'dl':
                iperf_local_cmd = iperf_local_cmd.format(bind=bind_ip)
        # iperf_remote_cmd = iperf_remote_cmd.format(bind='-B {}'.format(
        #     self.iperf_traffic_ip))
        return iperf_local_cmd, iperf_remote_cmd

    def stop_data(self, alias):
        """Stop data"""
        # Client should be stopped first
        if self.direction.lower() == 'ul':
            self.iperfuepc_process.stop_process(signal='2')
            time.sleep(5)
            # self.iperf_process.stop_process_iperf_pc(signal='2')
            self.iperfpc_process.stop_process(signal='2')
        elif self.direction.lower() == 'dl':
            self.iperfpc_process.stop_process(signal='2')
            time.sleep(5)
            self.iperfuepc_process.stop_process(signal='2')
        return self._get_throughput()

    def _start_ssh_to_iperf_pc(self):
        prompt = get_config_variable(['iperf', self.iperf_section, 'prompt'])
        if prompt is None:
            prompt = '#'
        ssh_client = SSHClient(get_config_variable(['iperf',
                                                    self.iperf_section, 'ip']),
                               port=22, prompt=prompt, timeout=10)
        ssh_client.login(get_config_variable(['iperf', self.iperf_section, 'user']),
                         get_config_variable(['iperf', self.iperf_section, 'password']))
        return ssh_client

    def _start_ssh_to_ue_pc(self):
        mobile_params = get_config_variable(['ue_devices', self.rat, self.device_name])
        prompt = get_config_variable(['ue_devices', self.rat, self.device_name, 'prompt'])
        if prompt is None:
            prompt = '$'
        if mobile_params.get('remote_ip'):
            logger.debug("Its a remote UE. Starting SSH session")
            ssh_client = SSHClient(get_config_variable(['ue_devices', self.rat,
                                                        self.device_name, 'remote_ip']),
                                   port=22, prompt=prompt, timeout=10)
            ssh_client.login(get_config_variable(['ue_devices', self.rat, self.device_name,
                                                  'remote_user']),
                             get_config_variable(['ue_devices', self.rat, self.device_name,
                                                  'remote_password']))
        else:
            ssh_client = None
        return ssh_client

    def _get_throughput(self):
        remote_log = self.iperfpc_process.get_log_file()
        local_log = self.iperfuepc_process.get_log_file()
        # remote_log, local_log = self.iperf_process.get_log_files()
        logger.debug("Remote log filename: {}".format(remote_log))
        logger.debug("Local log filename: {}".format(local_log))
        for log_file in [remote_log, local_log]:
            if 'server' in log_file:
                return self._parse_iperf_log(log_file)

    def _parse_iperf_log(self, log_file):
        with open(log_file) as iperf_log:
            all_lines = iperf_log.readlines()
            logger.debug('iperf summary lines')
            logger.debug(str(all_lines))
            if not any("sec" in line for line in all_lines):
                raise NoDataReceivedAtIperfServerException
            else:
                data_rates_list = []
                duration = data = packet_loss = ''
                full_regex = self._build_regex()
                for line in all_lines:
                    logger.debug('line for match: {}'.format(line))
                    match = re.search(full_regex, line, re.I)
                    if match:
                        logger.debug('line matches regex')
                        duration = match.group(1)
                        data = match.group(2)
                        data_rate = match.group(4)
                        packet_loss = match.group(6)
                        logger.debug('data_rate {}'.format(data_rate))
                        data_rates_list.append(data_rate)
                        if duration.startswith('0.0') and '1.0' not in duration:
                            return min(data_rates_list), max(data_rates_list), data, packet_loss, duration
                else:
                    logger.warn('IPERF SUMMARY LINE NOT FOUND')
                    logger.debug('data_rate_list: {}'.format(str(data_rates_list)))
                    return min(data_rates_list), max(data_rates_list), '', '', ''

    def _build_regex(self):
        duration_regex = r'\d+\.\d+-\s*\d+\.\d+'
        # float_regex = '\d+\.\d+'
        # int_regex = '\d+'
        bytes_or_bits_regex = r'\w(bytes|bits)'
        any_regex = '.*?'
        full_regex = r'({0})\s*sec\s*({1})\s*{2}\s*({3})\s*{4}/sec{5}\(({6})%\)'.format(
            duration_regex, any_regex, bytes_or_bits_regex, any_regex,
            bytes_or_bits_regex, any_regex, any_regex)
        # full_regex = '({0})\s+sec{1}({2})\s+.{3}{4}({5})\s+.{6}/sec{7}\(({8})%\)'.format(
        #     duration_regex, any_regex, int_regex, bytes_or_bits_regex,
        #     any_regex, float_regex, bytes_or_bits_regex, any_regex, any_regex)
        logger.info('Iperf log lines Regex {} '.format(full_regex))
        return full_regex

    def _create_iperf_processes(self, iperf_pc_ssh_client, ue_pc_ssh_client):
        self.iperfpc_process = IperfProcess(iperf_pc_ssh_client)
        if self.android_version is not None and int(self.android_version) >= 900:
            self.iperfuepc_process = IperfProcessInteractiveShell(ue_pc_ssh_client)
            self._enter_ue_manager_scope(ue_pc_ssh_client)
        else:
            self.iperfuepc_process = IperfProcess(ue_pc_ssh_client)

    def _enter_ue_manager_scope(self, ue_pc_ssh_client):
        logger.info('_enter_ue_manager_scope')
        ue_pc_ssh_client.write('adb -s {} shell \n'.format(self.adb_id))
        time.sleep(1)
        output = ue_pc_ssh_client.read()
        logger.info(output)
#        ue_pc_ssh_client.write('run-as com.nokia.syve.uemanager.mobile \n')
        ue_pc_ssh_client.write('run-as com.nokia.android.application \n')
        time.sleep(1)
        output = ue_pc_ssh_client.read()
        logger.info(output)

